67	pub fn status<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
68	    ws: &Workspace<'_, R, D>,
69	    inference: &I,
70	    opts: &StatusOptions,
71	) -> Result<StatusReport, GraphError> {
72	    let mut packages = Vec::new();
73	    let ids = ws.report_ids();
74	    let base_versions = ws.base_versions()?;
75	    let (loaded_changesets, changeset_load_failures) = crate::load_changesets_permissive(&ws.root, &ws.config)?;
76	    let tags = ws.tags()?;
77	
78	    let all_packages: Vec<&Package> = ws.graph.packages().collect();
79	    let pending = resolve_pending_changesets(all_packages.iter().copied(), &ws.identity, &loaded_changesets)?;
80	
81	    // Pending severity is `plan_version`'s own
82	    // `PlannedBump.severity` per package -- the same cascade/fixed/linked-group
83	    // computation `callisto version` uses. status computes no cascade of its
84	    // own; it only reads the plan `plan_version` already derives.
85	    let version_opts = VersionOptions {
86	        strict: opts.strict,
87	        allow_empty_changesets: true,
88	    };
89	    // An ambiguous changeset entry, or an unparseable changeset file, makes `plan_version`
90	    // (via `aggregate`'s own strict `load_changesets`) hard-error -- the right behavior for a
91	    // real `version`/`release` run, but `status` must survive both and report
92	    // `AmbiguousPackageName`/the parse failure diagnostic below instead. Severity planning is
93	    // skipped for this run rather than duplicating `aggregate`'s own resolution to route
94	    // around its error.
95	    let plan = match plan_version(ws, inference, &version_opts) {
96	        Ok(plan) => Some(plan),
97	        Err(GraphError::AmbiguousName { .. } | GraphError::ParseChangeset { .. }) => None,
98	        Err(e) => return Err(e),
99	    };
100	    let planned_severity: BTreeMap<PackageId, Severity> = plan
101	        .iter()
102	        .flat_map(|plan| &plan.bumps)
103	        .map(|b| (b.package.clone(), b.severity))
104	        .collect();
105	
106	    let changed = changed_since_last_tag(&all_packages, tags, ws.git_access())?;
107	
108	    for pkg in all_packages.iter().copied() {
109	        let current_version = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
110	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
111	                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
112	                field: "version",
113	            })
114	        })?;
115	        let last = tags.last_tag(&pkg.id);
116	        let last_tag = last.map(|t| t.name.clone());
117	        let last_released_version = last.map(|t| t.version.clone());
118	
119	        let (pkg_changesets, _) = pending.get(&pkg.id).cloned().unwrap_or_default();
120	        let pending_severity = planned_severity.get(&pkg.id).copied();
121	
122	        packages.push(callisto_model::StatusPackageRecord {
123	            package: ids.of(&pkg.id),
124	            current_version,
125	            last_tag,
126	            last_released_version,
127	            pending_severity,
128	            changed_since_last_tag: changed[&pkg.id],
129	            release_trigger: pkg.release_trigger,
130	            pending_changesets: pkg_changesets,
131	        });
132	    }
133	
134	    let mut diagnostics = ws.graph.diagnostics().to_vec();
135	    diagnostics.extend(tags.diagnostics.iter().cloned());
136	    // Fold in every changeset well-formedness diagnostic (EmptyChangeset, UnknownPackage, AmbiguousPackageName,
137	    // InvalidPackageName).
138	    diagnostics.extend(changeset_wellformedness_diagnostics(
139	        all_packages.iter().copied(),
140	        &ws.identity,
141	        &loaded_changesets,
142	    )?);
143	    for failure in &changeset_load_failures {
144	        diagnostics.push(Diagnostic {
145	            code: DiagnosticCode::ChangesetParseFailed,
146	            severity: DiagnosticSeverity::Error,
147	            message: format!("{}: {}", failure.path.display(), failure.source),
148	            package: None,
149	            path: Some(failure.path.clone()),
150	            governed_by: None,
151	            escalated_by: None,
152	        });
153	    }
154	    for bump in plan.iter().flat_map(|plan| &plan.bumps) {
155	        let Some(BumpReason::Inference { commits, .. }) = &bump.reason else {
156	            continue;
157	        };
158	        let has_changeset = packages
159	            .iter()
160	            .any(|record| record.package == ids.of(&bump.package) && !record.pending_changesets.is_empty());
161	        if has_changeset {
162	            continue;
163	        }
164	        diagnostics.push(Diagnostic {
165	            code: DiagnosticCode::InferredReleaseWithoutChangeset,
166	            severity: DiagnosticSeverity::Warning,
167	            message: format!(
168	                "`{}` has a pending release inferred from {commits} commit(s) and no changeset; the release pull request reads changesets only, so add one to release it",
169	                bump.package.display_name()
170	            ),
171	            package: Some(bump.package.clone()),
172	            path: None,
173	            governed_by: None,
174	            escalated_by: None,
175	        });
176	    }
177	    escalate(&mut diagnostics, opts.strict);
178	    ids.diagnostics(&mut diagnostics);
179	
180	    let has_changesets = packages.iter().any(|p| !p.pending_changesets.is_empty());
181	    // Count of packages with a planned bump, post-cascade/fixed/linked-group --
182	    // the field a script now reads to detect pending changesets, since `--check`'s
183	    // exit code no longer signals it.
184	    let pending = packages.iter().filter(|p| p.pending_severity.is_some()).count() as u32;
185	
186	    Ok(StatusReport {
187	        schema_version: PACKAGE_REPORT_SCHEMA_VERSION,
188	        has_changesets,
189	        pending,
190	        packages,
191	        diagnostics,
192	    })
193	}
