195	/// The per-changeset well-formedness diagnostics: entries shape and package-name resolution. Resolves through the same identity index
196	/// `resolve_pending_changesets` does, but this scan must never abort early,
197	/// so an unknown or ambiguous entry becomes a diagnostic instead of an
198	/// early return.
199	///
200	/// An entries-empty changeset is advisory only (`Info`): `@changesets/cli add --empty`
201	/// produces one deliberately, so it is not a well-formedness problem. A changeset with
202	/// entries but an empty summary never reaches this scan at all -- `load_changesets_permissive`
203	/// already rejects that shape at parse time, surfacing it as a `ChangesetParseFailed`
204	/// diagnostic instead.
205	fn changeset_wellformedness_diagnostics<'a>(
206	    packages: impl Iterator<Item = &'a Package> + Clone,
207	    identity: &IdentityIndex,
208	    loaded: &[LoadedChangeset],
209	) -> Result<Vec<Diagnostic>, GraphError> {
210	    let mut diagnostics = Vec::new();
211	    for cs in loaded {
212	        if cs.changeset.entries.is_empty() {
213	            diagnostics.push(Diagnostic {
214	                code: DiagnosticCode::EmptyChangeset,
215	                severity: DiagnosticSeverity::Info,
216	                message: format!("Changeset `{}` is empty", cs.path.display()),
217	                package: None,
218	                path: Some(cs.path.clone()),
219	                governed_by: None,
220	                escalated_by: None,
221	            });
222	        }
223	
224	        for entry in &cs.changeset.entries {
225	            match PackageId::parse(&entry.name) {
226	                Ok(id) => match resolve_target_package(packages.clone(), identity, &id) {
227	                    Ok(None) => {
228	                        diagnostics.push(Diagnostic {
229	                            code: DiagnosticCode::UnknownPackage,
230	                            severity: DiagnosticSeverity::Error,
231	                            message: format!(
232	                                "Changeset `{}` references unknown package `{}`",
233	                                cs.path.display(),
234	                                entry.name
235	                            ),
236	                            package: Some(id),
237	                            path: Some(cs.path.clone()),
238	                            governed_by: None,
239	                            escalated_by: None,
240	                        });
241	                    }
242	                    Ok(Some(_)) => {}
243	                    Err(GraphError::AmbiguousName { candidates, .. }) => {
244	                        let names: Vec<String> = candidates.iter().map(|id| id.display_name().to_string()).collect();
245	                        diagnostics.push(Diagnostic {
246	                            code: DiagnosticCode::AmbiguousPackageName,
247	                            severity: DiagnosticSeverity::Error,
248	                            message: format!(
249	                                "Changeset `{}` references ambiguous package `{}` (matches: {})",
250	                                cs.path.display(),
251	                                entry.name,
252	                                names.join(", ")
253	                            ),
254	                            package: Some(id),
255	                            path: Some(cs.path.clone()),
256	                            governed_by: None,
257	                            escalated_by: None,
258	                        });
259	                    }
260	                    Err(e) => return Err(e),
261	                },
262	                Err(_) => {
263	                    diagnostics.push(Diagnostic {
264	                        code: DiagnosticCode::InvalidPackageName,
265	                        severity: DiagnosticSeverity::Error,
266	                        message: format!(
267	                            "Changeset `{}` contains invalid package name `{}`",
268	                            cs.path.display(),
269	                            entry.name
270	                        ),
271	                        package: None,
272	                        path: Some(cs.path.clone()),
273	                        governed_by: None,
274	                        escalated_by: None,
275	                    });
276	                }
277	            }
278	        }
279	    }
280	    Ok(diagnostics)
281	}
