18	#[derive(Clone, Debug, Default)]
19	pub struct StatusOptions {
20	    pub strict: bool,
21	}
22	
23	/// Per-package accumulator: pending changeset names and their max severity.
24	type PendingChangesets = BTreeMap<PackageId, (Vec<String>, Option<Severity>)>;
25	
26	/// Resolves each changeset entry to at most one package through the identity index -- the
27	/// resolver `callisto version` uses -- and accumulates the pending changeset names and max
28	/// severity per package.
29	///
30	/// An unknown or ambiguous entry is skipped here rather than hard-erroring:
31	/// `changeset_wellformedness_diagnostics` reports both cases as an Error-severity diagnostic.
32	fn resolve_pending_changesets<'a>(
33	    packages: impl Iterator<Item = &'a Package> + Clone,
34	    identity: &IdentityIndex,
35	    loaded_changesets: &[LoadedChangeset],
36	) -> Result<PendingChangesets, GraphError> {
37	    let mut pending: PendingChangesets = BTreeMap::new();
38	    for lc in loaded_changesets {
39	        for entry in &lc.changeset.entries {
40	            let Ok(entry_id) = PackageId::parse(&entry.name) else {
41	                continue;
42	            };
43	            let resolved = match resolve_target_package(packages.clone(), identity, &entry_id) {
44	                Ok(Some(resolved)) => resolved,
45	                Ok(None) | Err(GraphError::AmbiguousName { .. }) => continue,
46	                Err(e) => return Err(e),
47	            };
48	            let name = lc
49	                .path
50	                .file_stem()
51	                .and_then(|s| s.to_str())
52	                .unwrap_or("unknown")
53	                .to_string();
54	            let state = pending.entry(resolved.id.clone()).or_default();
55	            if state.0.last() != Some(&name) {
56	                state.0.push(name);
57	            }
58	            state.1 = match (state.1, entry.severity) {
59	                (None, s) => Some(s),
60	                (Some(cur), s) => Some(cur.max(s)),
61	            };
62	        }
63	    }
64	    Ok(pending)
65	}
66	
67	pub fn status<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
68	    ws: &Workspace<'_, R, D>,
69	    inference: &I,
70	    opts: &StatusOptions,
71	) -> Result<StatusReport, GraphError> {
72	    let mut packages = Vec::new();
73	    let ids = ws.report_ids();
74	    let base_versions = ws.base_versions()?;
75	    let (loaded_changesets, changeset_load_failures) = crate::load_changesets_permissive(&ws.root, &ws.config)?;
76	    let tags = ws.tags()?;
77	
78	    let all_packages: Vec<&Package> = ws.graph.packages().collect();
79	    let pending = resolve_pending_changesets(all_packages.iter().copied(), &ws.identity, &loaded_changesets)?;
80	
81	    // Pending severity is `plan_version`'s own
82	    // `PlannedBump.severity` per package -- the same cascade/fixed/linked-group
83	    // computation `callisto version` uses. status computes no cascade of its
84	    // own; it only reads the plan `plan_version` already derives.
85	    let version_opts = VersionOptions {
86	        strict: opts.strict,
87	        allow_empty_changesets: true,
88	    };
89	    // An ambiguous changeset entry, or an unparseable changeset file, makes `plan_version`
90	    // (via `aggregate`'s own strict `load_changesets`) hard-error -- the right behavior for a
91	    // real `version`/`release` run, but `status` must survive both and report
92	    // `AmbiguousPackageName`/the parse failure diagnostic below instead. Severity planning is
93	    // skipped for this run rather than duplicating `aggregate`'s own resolution to route
94	    // around its error.
95	    let plan = match plan_version(ws, inference, &version_opts) {
96	        Ok(plan) => Some(plan),
97	        Err(GraphError::AmbiguousName { .. } | GraphError::ParseChangeset { .. }) => None,
98	        Err(e) => return Err(e),
99	    };
100	    let planned_severity: BTreeMap<PackageId, Severity> = plan
101	        .iter()
102	        .flat_map(|plan| &plan.bumps)
103	        .map(|b| (b.package.clone(), b.severity))
104	        .collect();
105	
106	    let changed = changed_since_last_tag(&all_packages, tags, ws.git_access())?;
107	
108	    for pkg in all_packages.iter().copied() {
109	        let current_version = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
110	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
111	                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
112	                field: "version",
113	            })
114	        })?;
115	        let last = tags.last_tag(&pkg.id);
116	        let last_tag = last.map(|t| t.name.clone());
117	        let last_released_version = last.map(|t| t.version.clone());
118	
119	        let (pkg_changesets, _) = pending.get(&pkg.id).cloned().unwrap_or_default();
120	        let pending_severity = planned_severity.get(&pkg.id).copied();
121	
122	        packages.push(callisto_model::StatusPackageRecord {
123	            package: ids.of(&pkg.id),
124	            current_version,
125	            last_tag,
126	            last_released_version,
127	            pending_severity,
128	            changed_since_last_tag: changed[&pkg.id],
129	            release_trigger: pkg.release_trigger,
130	            pending_changesets: pkg_changesets,
131	        });
132	    }
133	
134	    let mut diagnostics = ws.graph.diagnostics().to_vec();
135	    diagnostics.extend(tags.diagnostics.iter().cloned());
136	    // Fold in every changeset well-formedness diagnostic (EmptyChangeset, UnknownPackage, AmbiguousPackageName,
137	    // InvalidPackageName).
138	    diagnostics.extend(changeset_wellformedness_diagnostics(
139	        all_packages.iter().copied(),
140	        &ws.identity,
141	        &loaded_changesets,
142	    )?);
143	    for failure in &changeset_load_failures {
144	        diagnostics.push(Diagnostic {
145	            code: DiagnosticCode::ChangesetParseFailed,
146	            severity: DiagnosticSeverity::Error,
147	            message: format!("{}: {}", failure.path.display(), failure.source),
148	            package: None,
149	            path: Some(failure.path.clone()),
150	            governed_by: None,
151	            escalated_by: None,
152	        });
153	    }
154	    for bump in plan.iter().flat_map(|plan| &plan.bumps) {
155	        let Some(BumpReason::Inference { commits, .. }) = &bump.reason else {
156	            continue;
157	        };
158	        let has_changeset = packages
159	            .iter()
160	            .any(|record| record.package == ids.of(&bump.package) && !record.pending_changesets.is_empty());
161	        if has_changeset {
162	            continue;
163	        }
164	        diagnostics.push(Diagnostic {
165	            code: DiagnosticCode::InferredReleaseWithoutChangeset,
166	            severity: DiagnosticSeverity::Warning,
167	            message: format!(
168	                "`{}` has a pending release inferred from {commits} commit(s) and no changeset; the release pull request reads changesets only, so add one to release it",
169	                bump.package.display_name()
170	            ),
171	            package: Some(bump.package.clone()),
172	            path: None,
173	            governed_by: None,
174	            escalated_by: None,
175	        });
176	    }
177	    escalate(&mut diagnostics, opts.strict);
178	    ids.diagnostics(&mut diagnostics);
179	
180	    let has_changesets = packages.iter().any(|p| !p.pending_changesets.is_empty());
181	    // Count of packages with a planned bump, post-cascade/fixed/linked-group --
182	    // the field a script now reads to detect pending changesets, since `--check`'s
183	    // exit code no longer signals it.
184	    let pending = packages.iter().filter(|p| p.pending_severity.is_some()).count() as u32;
185	
186	    Ok(StatusReport {
187	        schema_version: PACKAGE_REPORT_SCHEMA_VERSION,
188	        has_changesets,
189	        pending,
190	        packages,
191	        diagnostics,
192	    })
193	}
194	
195	/// The per-changeset well-formedness diagnostics: entries shape and package-name resolution. Resolves through the same identity index
196	/// `resolve_pending_changesets` does, but this scan must never abort early,
197	/// so an unknown or ambiguous entry becomes a diagnostic instead of an
198	/// early return.
199	///
200	/// An entries-empty changeset is advisory only (`Info`): `@changesets/cli add --empty`
201	/// produces one deliberately, so it is not a well-formedness problem. A changeset with
202	/// entries but an empty summary never reaches this scan at all -- `load_changesets_permissive`
203	/// already rejects that shape at parse time, surfacing it as a `ChangesetParseFailed`
204	/// diagnostic instead.
205	fn changeset_wellformedness_diagnostics<'a>(
206	    packages: impl Iterator<Item = &'a Package> + Clone,
207	    identity: &IdentityIndex,
208	    loaded: &[LoadedChangeset],
209	) -> Result<Vec<Diagnostic>, GraphError> {
210	    let mut diagnostics = Vec::new();
211	    for cs in loaded {
212	        if cs.changeset.entries.is_empty() {
213	            diagnostics.push(Diagnostic {
214	                code: DiagnosticCode::EmptyChangeset,
215	                severity: DiagnosticSeverity::Info,
216	                message: format!("Changeset `{}` is empty", cs.path.display()),
217	                package: None,
218	                path: Some(cs.path.clone()),
219	                governed_by: None,
220	                escalated_by: None,
221	            });
222	        }
223	
224	        for entry in &cs.changeset.entries {
225	            match PackageId::parse(&entry.name) {
226	                Ok(id) => match resolve_target_package(packages.clone(), identity, &id) {
227	                    Ok(None) => {
228	                        diagnostics.push(Diagnostic {
229	                            code: DiagnosticCode::UnknownPackage,
230	                            severity: DiagnosticSeverity::Error,
231	                            message: format!(
232	                                "Changeset `{}` references unknown package `{}`",
233	                                cs.path.display(),
234	                                entry.name
235	                            ),
236	                            package: Some(id),
237	                            path: Some(cs.path.clone()),
238	                            governed_by: None,
239	                            escalated_by: None,
240	                        });
241	                    }
242	                    Ok(Some(_)) => {}
243	                    Err(GraphError::AmbiguousName { candidates, .. }) => {
244	                        let names: Vec<String> = candidates.iter().map(|id| id.display_name().to_string()).collect();
245	                        diagnostics.push(Diagnostic {
246	                            code: DiagnosticCode::AmbiguousPackageName,
247	                            severity: DiagnosticSeverity::Error,
248	                            message: format!(
249	                                "Changeset `{}` references ambiguous package `{}` (matches: {})",
250	                                cs.path.display(),
251	                                entry.name,
252	                                names.join(", ")
253	                            ),
254	                            package: Some(id),
255	                            path: Some(cs.path.clone()),
256	                            governed_by: None,
257	                            escalated_by: None,
258	                        });
259	                    }
260	                    Err(e) => return Err(e),
261	                },
262	                Err(_) => {
263	                    diagnostics.push(Diagnostic {
264	                        code: DiagnosticCode::InvalidPackageName,
265	                        severity: DiagnosticSeverity::Error,
266	                        message: format!(
267	                            "Changeset `{}` contains invalid package name `{}`",
268	                            cs.path.display(),
269	                            entry.name
270	                        ),
271	                        package: None,
272	                        path: Some(cs.path.clone()),
273	                        governed_by: None,
274	                        escalated_by: None,
275	                    });
276	                }
277	            }
278	        }
279	    }
280	    Ok(diagnostics)
281	}
