72	pub fn plan_version<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
73	    ws: &Workspace<'_, R, D>,
74	    inference: &I,
75	    opts: &VersionOptions,
76	) -> Result<VersionPlan, GraphError> {
77	    let base_versions = ws.base_versions()?;
78	    let tags = ws.tags()?;
79	
80	    let pre_path = ws.root.join(ws.config.pre_json_path());
81	    let pre_text = callisto_model::strict_fs::read_optional(&pre_path)
82	        .map_err(|e| GraphError::PreJsonRead { message: e.to_string() })?;
83	    let (pre_state, pre_json_original_text) = if let Some(text) = pre_text {
84	        let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
85	        let state = ws.resolve_pre_state_from_json(state, &text)?;
86	        (Some(state), Some(text))
87	    } else {
88	        (None, None)
89	    };
90	
91	    let mut agg = aggregate(
92	        &ws.graph,
93	        &ws.identity,
94	        &ws.config,
95	        ws.git_access(),
96	        tags,
97	        &base_versions,
98	        pre_state.as_ref(),
99	        inference,
100	    )?;
101	
102	    // For PreMode::Exit, inject a synthetic Patch severity for every package
103	    // that is currently at a pre-release version. This triggers bump_target
104	    // (which in Exit mode calls versioning.bump on the pre-release, stripping
105	    // the tag and finalizing to stable) even when no pending changeset files
106	    // exist on disk — they were consumed and deleted during the pre-release phase
107	    // and their stems recorded in pre.json.
108	    if let Some(ref pre) = pre_state
109	        && pre.mode == callisto_model::format::PreMode::Exit
110	    {
111	        for (id, ver) in &base_versions {
112	            if ver.is_prerelease() {
113	                agg.severities.entry(id.clone()).or_insert(Severity::Patch);
114	                agg.reasons
115	                    .entry(id.clone())
116	                    .or_insert(BumpReason::PreRelease { tag: pre.tag.clone() });
117	            }
118	        }
119	    }
120	
121	    let input = CascadeInput {
122	        graph: &ws.graph,
123	        groups: &ws.config.groups,
124	        cfg: &ws.config.cascade,
125	        seed: &agg.severities,
126	        reasons: &agg.reasons,
127	        named_by: &agg.named_by,
128	        base: &base_versions,
129	        pre: pre_state.as_ref(),
130	        tags,
131	        identity: &ws.identity,
132	    };
133	
134	    let napi = crate::napi::NapiTargetsIndex::load(&ws.config.groups, &ws.root, &ws.graph)?;
135	    let group_check =
136	        crate::groups::pre_mutation_checks(&ws.graph, &ws.config.groups, &base_versions, tags, &napi, &ws.root)?;
137	
138	    let outcome = run_cascade(input)?;
139	
140	    let mut bumps = Vec::new();
141	    let mut changelog_writes = Vec::new();
142	
143	    // PERF-006: build a map once so each lookup inside the loop is O(1)
144	    // instead of O(N) (the previous packages().find() call).
145	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
146	
147	    for (id, &sev) in &outcome.severities {
148	        if sev == Severity::None {
149	            continue;
150	        }
151	        let pkg = pkg_map
152	            .get(id)
153	            .copied()
154	            .expect("every bumped package is in the workspace");
155	        let from = base_versions.get(id).cloned().ok_or_else(|| {
156	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
157	                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
158	                field: "version",
159	            })
160	        })?;
161	        let to = outcome.targets.get(id).cloned().ok_or_else(|| {
162	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
163	                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
164	                field: "version",
165	            })
166	        })?;
167	
168	        let mut writes = Vec::new();
169	        for decl in &pkg.manifests {
170	            if decl.role == callisto_model::ManifestRole::Canonical {
171	                writes.push(VersionWriteTarget::Manifest(decl.path.clone()));
172	            }
173	        }
174	
175	        bumps.push(PlannedBump {
176	            package: id.clone(),
177	            from: from.clone(),
178	            to: to.clone(),
179	            severity: sev,
180	            governed_by: outcome.governed_by.get(id).cloned(),
181	            reason: outcome.reasons.get(id).cloned(),
182	            writes,
183	        });
184	
185	        if let Some(ch_path) = &pkg.changelog {
186	            let mut input = match agg.changelog_inputs.get(id).cloned() {
187	                Some(mut agg_input) => {
188	                    // Real changeset data: use it, but set the resolved target version.
189	                    agg_input.from = from.clone();
190	                    agg_input.to = Some(to.clone());
191	                    if let Some(reason) = outcome.reasons.get(id)
192	                        && let Some(source) = map_reason_to_change_source(reason, id, &to, &outcome, &agg)
193	                    {
194	                        agg_input.entries.push(ChangelogEntry { severity: sev, source });
195	                    }
196	                    agg_input
197	                }
198	                _ => {
199	                    // No changeset drove this bump (cascade, group, inference, pre-release).
200	                    // Synthesize a single entry describing the reason so that render_section()
201	                    // never receives an empty entries list (which returns EmptyInput).
202	                    let source = outcome
203	                        .reasons
204	                        .get(id)
205	                        .and_then(|r| map_reason_to_change_source(r, id, &to, &outcome, &agg))
206	                        .unwrap_or_else(|| ChangeSource::Changeset {
207	                            filename: String::new(),
208	                            summary: format!(
209	                                "Version bump ({})",
210	                                match sev {
211	                                    Severity::Major => "major",
212	                                    Severity::Minor => "minor",
213	                                    Severity::Patch => "patch",
214	                                    Severity::None => "none",
215	                                }
216	                            ),
217	                        });
218	                    ChangelogInput {
219	                        package: id.clone(),
220	                        from: from.clone(),
221	                        to: Some(to.clone()),
222	                        entries: vec![ChangelogEntry { severity: sev, source }],
223	                    }
224	                }
225	            };
226	
227	            if let Some(group_name) = group_check
228	                .new_members
229	                .iter()
230	                .find(|(_, members)| members.contains(id))
231	                .map(|(name, _)| name.clone())
232	            {
233	                input.entries.push(ChangelogEntry {
234	                    severity: sev,
235	                    source: ChangeSource::NewGroupMember { group: group_name },
236	                });
237	            }
238	
239	            changelog_writes.push(crate::plan::ChangelogWrite {
240	                changelog_path: ch_path.clone(),
241	                input,
242	            });
243	        }
244	    }
245	
246	    let is_pre_mode = pre_state
247	        .as_ref()
248	        .map(|s| s.mode == callisto_model::format::PreMode::Pre)
249	        .unwrap_or(false);
250	    // In pre mode a changeset already recorded in pre.json is not pending: a rerun plans nothing for it.
251	    let nothing_pending = if is_pre_mode {
252	        agg.new_pre_changesets.is_empty()
253	    } else {
254	        agg.consumed.is_empty()
255	    };
256	
257	    // Reading the changesets comes first: an entry that names no package leaves its changeset on disk.
258	    let mut diagnostics = agg.diagnostics.clone();
259	    diagnostics.extend(outcome.diagnostics);
260	    diagnostics.extend(group_check.diagnostics);
261	    if nothing_pending && !opts.allow_empty_changesets && !ws.config.validation.allow_empty_changesets {
262	        diagnostics.push(callisto_model::Diagnostic {
263	            code: callisto_model::DiagnosticCode::EmptyChangeset,
264	            severity: callisto_model::DiagnosticSeverity::Warning,
265	            message: "No pending changesets found in workspace".to_string(),
266	            package: None,
267	            path: None,
268	            escalated_by: Some(callisto_model::StrictFlag::Strict),
269	            governed_by: Some(callisto_model::ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS),
270	        });
271	    }
272	
273	    escalate(&mut diagnostics, opts.strict);
274	
275	    let (pre_state_update, delete_pre_json) = if let Some(mut state) = pre_state {
276	        if state.mode == callisto_model::format::PreMode::Exit {
277	            (None, Some(ws.config.pre_json_path()))
278	        } else {
279	            // Records ids aggregate() determined are newly-seen this run; see Aggregation::new_pre_changesets.
280	            for id in &agg.new_pre_changesets {
281	                if !state.changesets.iter().any(|s| s == id) {
282	                    state.changesets.push(id.clone());
283	                }
284	            }
285	            (Some(state), None)
286	        }
287	    } else {
288	        (None, None)
289	    };
290	
291	    let targets = bumps.iter().map(|b| (b.package.clone(), b.to.clone())).collect();
292	    let (platform_writes, optional_dep_updates) = platform_version_writes(ws, &targets)?;
293	
294	    Ok(VersionPlan {
295	        bumps,
296	        rewrites: outcome.rewrites.into_values().collect(),
297	        platform_writes,
298	        optional_dep_updates,
299	        changelog_writes,
300	        consumed_changesets: agg.consumed,
301	        pre_state_update,
302	        pre_json_path: ws.config.pre_json_path(),
303	        pre_json_original_text,
304	        delete_pre_json,
305	        pre_cursor_updates: Vec::new(),
306	        observed_versions: base_versions,
307	        diagnostics,
308	    })
309	}
