695	/// The D01 defect was `cargo info` run without `--registry`: inside the
696	/// workspace it resolves the local manifest and reports the unpublished
697	/// version as already published. Observation is `cargo info` again -- so that
698	/// registry resolution and credentials are the package manager's job -- and the
699	/// property that makes it safe is asserted directly: every `cargo info` the
700	/// release path issues names a registry explicitly, and it is issued from the
701	/// workspace root where that registry is defined.
702	#[test]
703	fn red_d01_every_cargo_info_observation_names_a_registry_explicitly() {
704	    let e = RigEnv::single();
705	    let out = e.run(&[]);
706	    assert!(out.status.success(), "{}", stderr(&out));
707	
708	    let calls = e.rig.cargo_calls();
709	    let info: Vec<&(String, String)> = calls
710	        .iter()
711	        .filter(|(_, argv)| argv.split_whitespace().any(|word| word == "info"))
712	        .collect();
713	    assert!(
714	        !info.is_empty(),
715	        "the registry must be observed through cargo, got {calls:?}"
716	    );
717	    for (_, argv) in &info {
718	        assert!(
719	            argv.starts_with("--config net.retry=0 info "),
720	            "callisto's bounded retry owns retrying; cargo's own retry must be off: {argv}"
721	        );
722	    }
723	    for (cwd, argv) in &info {
724	        assert!(
725	            argv.contains(" --registry "),
726	            "`cargo {argv}` has no --registry, so it would answer from the local manifest"
727	        );
728	        assert_eq!(
729	            std::fs::canonicalize(cwd).unwrap(),
730	            std::fs::canonicalize(e.root()).unwrap(),
731	            "observation must run from the workspace root whose config defines the registry"
732	        );
733	    }
734	    assert!(
735	        calls
736	            .iter()
737	            .all(|(_, argv)| argv.starts_with("--config net.retry=0 info ") || argv.starts_with("publish ")),
738	        "only observation and the publish effect may shell to cargo, got {calls:?}"
739	    );
740	    assert_eq!(
741	        e.rig.log_count("cargo publish"),
742	        1,
743	        "an unpublished version must be published"
744	    );
745	}
